def F():
	MAX = 10 ** 9 + 1
	for _ in range(int(input())):
		(N, M, K) = [int(x) for x in input().split()]
		S = [int(x) for x in input()]
		XYW = [[int(x) for x in input().split()] for i in range(M)]
		cost = [[MAX for i in range(10)] for j in range(10)]
		for i in range(10):
			cost[i][i] = 0
		for [x, y, w] in XYW:
			cost[x][y] = w
		for p in range(10):
			for i in range(10):
				for j in range(10):
					cost[i][j] = min(cost[i][j], cost[i][p] + cost[p][j])
		coins_used = [0] * (1 + N // 2)
		for p in range(N // 2, 0, -1):
			coins = MAX
			for i in range(10):
				coins = min(coins, cost[S[p - 1]][i] + cost[S[N - p]][i])
			coins_used[p - 1] = coins_used[p] + coins
		if coins_used[0] > K:
			print(-1)
			continue
		ans = ''
		extra_coins = K - coins_used[0]
		for p in range(N // 2):
			for i in range(9, -1, -1):
				this_cost = cost[S[p]][i] + cost[S[N - p - 1]][i]
				old_cost = coins_used[p] - coins_used[p + 1]
				if this_cost <= extra_coins + old_cost:
					ans += str(i)
					extra_coins -= this_cost - old_cost
					break
		if N % 2:
			for i in range(9, -1, -1):
				if extra_coins >= cost[S[N // 2]][i]:
					ans += str(i)
					break
		for i in range(N // 2 - 1, -1, -1):
			ans += ans[i]
		print(ans)
F()
